from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
catalog=(R/'motion/motion.json').read_text()
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>千夏 R06 · 十二状态动画候选</title>
<style>*{box-sizing:border-box}body{margin:0;background:#161b25;color:#e9eef6;font:15px/1.6 system-ui,sans-serif}header{max-width:1180px;margin:auto;padding:32px 24px 16px}h1{margin:0;font-size:28px}p{color:#b4becd}button,select,input{font:inherit}button,select{border:1px solid #495568;border-radius:8px;padding:8px 14px;background:#263347;color:#fff;cursor:pointer}.bar{display:flex;gap:10px;flex-wrap:wrap;position:sticky;top:0;background:#161b25ee;padding:12px 24px;z-index:3;border-bottom:1px solid #343e4e}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(248px,1fr));gap:16px;max-width:1180px;margin:20px auto;padding:0 24px}.card{background:#212b3b;border:1px solid #39465b;border-radius:14px;overflow:hidden}h2{font-size:17px;margin:12px 16px 0}.desc{font-size:13px;margin:2px 16px 12px;min-height:40px;color:#bac6d7}.stage{display:flex;justify-content:center;align-items:center;min-height:228px;background:#30303f;overflow:auto}.stage canvas{width:192px;height:208px;flex-shrink:0}.card footer{padding:10px 14px;font-size:12px;color:#abb9cc}.card button{font-size:12px;padding:5px 9px}.zoom canvas{width:384px;height:416px}.zoom .grid{grid-template-columns:repeat(auto-fit,minmax(410px,1fr))}.zoom .stage{min-height:436px}.white .stage{background:white}.black .stage{background:#000}.magenta .stage{background:#f0f}.checker .stage{background:repeating-conic-gradient(#bbb 0 25%,#eee 0 50%) 0/24px 24px}a{color:#8bdde6}.status{max-width:1140px;margin:12px auto;padding:12px 20px;background:#263246;border-radius:8px}input[type=range]{width:100%;margin-top:8px}</style>
<header><h1>千夏 R06 · 十二状态动画候选</h1><p>头颈和家具固定，动作来自目光、手和正在使用的道具。回答、等待回应和遇到问题只提示一次，之后安静停留。</p><p>当前为制作检查版，独立评审结果以随附报告为准。尚未接入桌面 App。</p></header>
<div class="bar"><button id="toggle">暂停</button><button id="restart">重新开始 / 新事件</button><button id="zoom">放大 2 倍</button><select id="speed"><option value="1">真实速度</option><option value="0.25">四分之一速度</option></select><select id="bg"><option value="">深灰背景</option><option value="white">白色背景</option><option value="black">黑色背景</option><option value="magenta">洋红背景</option><option value="checker">棋盘格背景</option></select><button id="blink">眨眼：开</button><button id="step">下一帧</button></div><div class="status" id="status">正在读取动画…</div><main class="grid" id="grid"></main>
<script>const DATA=__CATALOG__;
const names={idle:['待机','拨一下悬浮球，等它安定。'],thinking:['思考','目光在节点间停留，托腮手固定。'],read_file:['读文件','按顺序阅读三张卡，双手固定。'],view_image:['看图片','笔和手一起换位，停下来检查。'],write_file:['写文件','双手错开敲击，短句之间有停顿。'],verify:['验证','触点检测、等待，再抬起探针。'],read_web:['浏览网页','点一次链接，再停下来读。'],default_work:['工作中','滚动轨迹球，观察，再微调。'],respond:['回答','递出卡片一次，然后稳定持卡。'],task_complete:['完成','安静趴桌，主体和对号固定。'],question_for_user:['等待回应','短按一次按钮，然后等你。'],failed:['遇到问题','轻抬故障卡一次，保持提示。']};
let paused=false,speed=1,blink=true,time=0,last=performance.now();const players=[];
function load(path){return new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>resolve(im);im.onerror=()=>reject(path);im.src='motion/'+path})}
function select(s,t){const dur=s.durationsMs.reduce((a,b)=>a+b,0),lead=s.durationsMs.slice(0,s.loopStart).reduce((a,b)=>a+b,0);let ms=t*1000;if(ms>=dur)ms=lead+(ms-lead)%(dur-lead);for(let i=0;i<s.sequence.length;i++){if(ms<s.durationsMs[i])return [s.sequence[i],i];ms-=s.durationsMs[i]}return[s.sequence.at(-1),s.sequence.length-1]}
const blinkEvents=[];let blinkSeed=48173,blinkEnd=0;
function rng(){blinkSeed=(1664525*blinkSeed+1013904223)>>>0;return blinkSeed/4294967296}
function extendBlinks(t){while(blinkEnd<t+10){let start=blinkEnd+2.8+4.2*rng(),duration=.18+.08*rng();blinkEvents.push([start,duration]);blinkEnd=start+duration;if(rng()<.10){start=blinkEnd+.12;duration=.18+.08*rng();blinkEvents.push([start,duration]);blinkEnd=start+duration}}}
function level(t,i){if(!blink)return 0;extendBlinks(t);for(const [start,d]of blinkEvents){const f=(t-start)/d;if(f<0)break;if(f<=1){const a=f<.38?f/.38:f<.5?1:(1-f)/.5;return Math.max(1,Math.min(6,Math.ceil(a*6)))}}return 0}

async function init(){for(const [i,s]of DATA.states.entries()){const card=document.createElement('article');card.className='card';const title=names[s.id];card.innerHTML='<h2>'+title[0]+'</h2><p class="desc">'+title[1]+'</p><div class="stage"><canvas width="384" height="416"></canvas></div><footer><span class="meter"></span><br><button class="new-event">新事件</button> <button class="refresh">同一事件刷新</button><input aria-label="'+title[0]+'逐帧检查" type="range" min="0" max="'+(s.sequence.length-1)+'" value="0"></footer>';grid.append(card);let p={s,i,card,body:await load(s.asset),eye:s.blink?await load(s.blink.asset):null,canvas:card.querySelector('canvas'),offset:0,eventId:0,forced:null};p.ctx=p.canvas.getContext('2d');card.querySelector('.new-event').onclick=()=>receiveEvent(p,p.eventId+1);card.querySelector('.refresh').onclick=()=>receiveEvent(p,p.eventId);card.querySelector('input').oninput=e=>{paused=true;p.forced=+e.target.value;document.querySelector('#toggle').textContent='继续';draw(p)};players.push(p)}status.textContent='资源已读取。默认 192×208 实际显示尺寸，可暂停逐帧、放大和切换背景检查。';requestAnimationFrame(tick)}
const eventLog=[];function receiveEvent(p,id){const old=p.eventId,before=p.offset;if(id!==old){p.eventId=id;p.offset=time;p.forced=null}eventLog.push({state:p.s.id,id,previousId:old,time,restarted:id!==old,before,after:p.offset});status.textContent=id===old?"同一事件刷新：继续当前动作或保持，不重新提示。":"新事件：重新触发一次动作。"}
function draw(p){const {s,ctx}=p;const t=Math.max(0,time-p.offset);let [f,idx]=select(s,t);if(p.forced!==null){idx=p.forced;f=s.sequence[idx]}ctx.clearRect(0,0,384,416);ctx.drawImage(p.body,f%s.columns*384,Math.floor(f/s.columns)*416,384,416,0,0,384,416);const l=level(time,p.i);if(l&&s.blink){let b=s.blink,n=b.frames[f][l-1];ctx.clearRect(b.x,b.y,b.width,b.height);ctx.drawImage(p.eye,n%b.columns*b.width,Math.floor(n/b.columns)*b.height,b.width,b.height,b.x,b.y,b.width,b.height)}const d=s.durationsMs.reduce((a,b)=>a+b,0)/1000;p.card.querySelector('.meter').textContent=s.mode==='enter_then_hold'?(t<d-s.durationsMs.at(-1)/1000?'进入动作':'稳定停留'):(s.mode==='static'?'静止姿态':'已播放 '+Math.floor(t/d)+' 轮');if(p.forced===null)p.card.querySelector('input').value=idx}
function tick(now){if(!paused)time+=Math.min((now-last)/1000,.1)*speed;last=now;players.forEach(draw);requestAnimationFrame(tick)}
document.querySelector('#toggle').onclick=e=>{paused=!paused;e.target.textContent=paused?'继续':'暂停';players.forEach(p=>p.forced=null)};document.querySelector('#restart').onclick=()=>{players.forEach(p=>receiveEvent(p,p.eventId+1));paused=false;document.querySelector('#toggle').textContent='暂停'};document.querySelector('#zoom').onclick=e=>{document.body.classList.toggle('zoom');e.target.textContent=document.body.classList.contains('zoom')?'实际尺寸':'放大 2 倍'};document.querySelector('#speed').onchange=e=>speed=+e.target.value;document.querySelector('#bg').onchange=e=>{for(const n of ['white','black','magenta','checker'])document.body.classList.remove(n);if(e.target.value)document.body.classList.add(e.target.value)};document.querySelector('#blink').onclick=e=>{blink=!blink;e.target.textContent='眨眼：'+(blink?'开':'关')};document.querySelector('#step').onclick=()=>{paused=true;players.forEach(p=>p.forced=((p.forced??select(p.s,time-p.offset)[1])+1)%p.s.sequence.length)};init().catch(e=>status.textContent='资源读取失败：'+e);</script></html>'''
# Explicit elements avoid the browser's built-in window.status name collision.
html=html.replace('const DATA=','const grid=document.querySelector("#grid"),status=document.querySelector("#status");const DATA=')
(R/'index.html').write_text(html.replace('__CATALOG__',catalog))
print('preview',R/'index.html')
